'use strict';
(()=>{
const dialog=document.createElement('dialog');dialog.className='approval-dialog';
dialog.innerHTML=`<div class="approval-heading"><h2>Согласование рассылки</h2><button class="outline" data-close>Закрыть</button></div><p>Одобряется конкретная версия только для имитации. SMTP и реальная отправка выключены.</p><p role="status" data-status></p><div data-content></div><label>Комментарий к решению<textarea data-comment maxlength="2000" rows="3" placeholder="Для возврата укажите, что нужно исправить"></textarea></label><div class="approval-actions"><button class="outline" data-action="submit">Отправить на проверку</button><button class="primary" data-action="approve">Одобрить для имитации</button><button class="outline" data-action="return">Вернуть с комментарием</button><button class="outline" data-refresh>Обновить состояние</button></div>`;
document.body.append(dialog);
const style=document.createElement('style');style.textContent=`.approval-dialog{width:min(940px,calc(100vw - 24px));max-width:940px;max-height:90vh;box-sizing:border-box;overflow:auto;border:1px solid #dce4ec;border-radius:10px;padding:24px;color:#193047}.approval-dialog::backdrop{background:#132d4266}.approval-heading,.approval-actions{display:flex;gap:10px;flex-wrap:wrap;align-items:center;justify-content:space-between}.approval-dialog button{width:auto;min-height:40px}.approval-dialog label,.approval-dialog textarea{display:block;width:100%;box-sizing:border-box}.approval-dialog textarea{margin:8px 0;padding:10px;border:1px solid #cfddea;border-radius:6px;font:inherit}.approval-dialog dd{margin:4px 0 14px;overflow-wrap:anywhere}.approval-dialog dt{font-weight:600}.approval-dialog iframe{width:100%;height:420px;border:1px solid #dce4ec;box-sizing:border-box}.approval-dialog [role=status]{white-space:pre-wrap}.approval-dialog textarea:focus{outline:none;border-color:#6BAEE0;box-shadow:0 0 0 2px #0795e918}@media(max-width:550px){.approval-dialog{padding:16px}.approval-actions button{flex:1 1 100%}.approval-heading h2{font-size:20px}.approval-dialog iframe{height:350px}}`;document.head.append(style);
const $=s=>dialog.querySelector(s);let cid=null,revision=null,approval=null,busy=false,rights={};
function el(tag,value){const n=document.createElement(tag);n.textContent=value??'';return n;}
function controls(){dialog.querySelectorAll('button,textarea').forEach(b=>b.disabled=busy);$('[data-action=submit]').disabled=busy||!rights.can_submit||approval?.status==='pending';for(const action of ['approve','return'])$('[data-action='+action+']').disabled=busy||!rights.can_review||approval?.status!=='pending';}
function date(value){return value?new Date(value).toLocaleString('ru-RU',{timeZone:'Asia/Qyzylorda'}):'—';}
function render(data,campaign){approval=data.approval;rights=data;revision=campaign.revision;const host=$('[data-content]');host.replaceChildren();
const s=approval.snapshot||{},t=s.template||{},sender=s.sender||{};const list=document.createElement('dl');
for(const [key,value] of [['Рассылка',campaign.name],['Статус',approval.label],['Версия на проверке',approval.campaign_revision||'—'],['Текущая версия',campaign.revision],['Отправил на проверку',`${approval.submitted_by||'—'} · ${date(approval.submitted_at)}`],['Решение',`${approval.reviewed_by||'—'} · ${date(approval.reviewed_at)}`],['Комментарий',approval.comment||'—']])list.append(el('dt',key),el('dd',value));
host.append(list);if(approval.reason)host.append(el('p',approval.reason));
if(s.template){host.append(el('h3','Версия, переданная на проверку'));const details=document.createElement('dl');
for(const [key,value]of [['Аудитории',(s.audiences||s.audience_ids||[]).join(', ')],['Получателей после исключений',s.counts?.ready??0],['Всего уникальных email',s.counts?.unique_emails??0],['Отправитель',`${sender.name||''} <${sender.email||''}>`],['Адрес для ответов',sender.reply_to||sender.email||'—'],['Расписание',s.schedule_mode==='scheduled'?`${date(s.scheduled_at)} (${s.timezone})`:'Ручной запуск'],['Тема',t.subject],['Прехедер',t.preheader]])details.append(el('dt',key),el('dd',value));host.append(details);
const iframe=document.createElement('iframe');iframe.title='Письмо на согласовании';iframe.setAttribute('sandbox','');iframe.referrerPolicy='no-referrer';const doc=new DOMParser().parseFromString(t.html||'','text/html');for(const n of doc.querySelectorAll('script,base,meta[http-equiv],iframe,object,embed,form,link'))n.remove();for(const n of doc.querySelectorAll('a,area')){n.removeAttribute('href');n.removeAttribute('target');}iframe.srcdoc=`<meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src data:; style-src 'unsafe-inline'; form-action 'none'; base-uri 'none'">`+doc.documentElement.outerHTML;host.append(iframe);}
controls();}
async function load(){const [data,campaign]=await Promise.all([api(`/api/campaigns/${cid}/approval`),api(`/api/campaigns/${cid}`)]);render(data,campaign);}
$('[data-close]').onclick=()=>dialog.close();$('[data-refresh]').onclick=async()=>{try{await load();$('[data-status]').textContent='Состояние обновлено.';}catch(e){$('[data-status]').textContent=e.message;}};
dialog.querySelectorAll('[data-action]').forEach(button=>button.onclick=async()=>{if(busy)return;busy=true;controls();try{await api(`/api/campaigns/${cid}/approval`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:button.dataset.action,version:approval.version,campaign_revision:revision,comment:$('[data-comment]').value})});$('[data-comment]').value='';await load();$('[data-status]').textContent='Решение сохранено в журнале. Письма не отправлялись.';document.dispatchEvent(new Event('campaign-approval-changed'));}catch(e){$('[data-status]').textContent=e.message;await load().catch(()=>{});}finally{busy=false;controls();}});
window.CampaignApproval={open:async id=>{cid=id;approval=null;rights={};busy=true;controls();$('[data-comment]').value='';$('[data-content]').replaceChildren();$('[data-status]').textContent='Загрузка…';if(!dialog.open)dialog.showModal();try{await load();$('[data-status]').textContent='';}catch(e){$('[data-status]').textContent=e.message;}finally{busy=false;controls();}}};
})();
